import torch, triton, triton.language as tl


@triton.jit(do_not_specialize=["n"])
def k(p, n, B: tl.constexpr):
    i = tl.arange(0, B)
    tl.store(p + i, tl.where(i < n, 1.0, 0.0))


@triton.jit
def k2(p, n, B: tl.constexpr):
    i = tl.arange(0, B)
    tl.store(p + i, tl.where(i < n, 1.0, 0.0))


x = torch.zeros(64, device="cuda")
for f, name in ((k, "dns"), (k2, "spec")):
    for n in (8, 16, 32):
        f[(1,)](x, n, 64)
        torch.cuda.synchronize()
        print(name, n, int(x.sum()))
    tot = sum(len(v) for v in f.cache.values())
    print(name, "compiled variants:", tot)

